#!/usr/bin/env python3
"""Build a local-only, consent-aware practice surface from the mobile payload."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAYLOAD = ROOT / "research/communication-job-mobile-lessons.json"
CURRICULUM = ROOT / "research/communication-job-curriculum-index.json"
OUT = ROOT / "writeups/communication-job-practice.html"


def main() -> int:
    payload = json.loads(PAYLOAD.read_text())
    curriculum = json.loads(CURRICULUM.read_text())
    phrase_forms = {
        lesson["canonical_job"]: [item["phrase_form"] for item in lesson.get("phrase_forms", [])]
        for lesson in curriculum["lessons"]
    }
    lessons = [
        dict(lesson, indexed_phrase_forms=phrase_forms.get(lesson["canonical_job"], []))
        for lesson in payload["lessons"]
    ]
    data = json.dumps(lessons, ensure_ascii=False).replace("</", "<\\/")
    options = "".join(
        f'<option value="{i}">{lesson["canonical_job"]}</option>'
        for i, lesson in enumerate(lessons)
    )
    document = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Communication Patterns Lab — Practice</title><style>:root{font-family:system-ui,sans-serif;color:#17202a;background:#f5f3ee}body{margin:0}header{background:#17212b;color:#fff;padding:24px max(20px,calc((100vw - 1050px)/2))}main{max-width:1050px;margin:20px auto;padding:0 20px 60px}.notice{background:#fff7d6;border:1px solid #d8bd61;border-radius:8px;padding:14px}.panel{background:#fff;border:1px solid #d7d0c5;border-radius:9px;padding:16px;margin:16px 0}label{display:block;margin:.7rem 0}select,input,textarea{font:inherit;padding:.55rem;box-sizing:border-box;max-width:100%}select,input{width:min(100%,520px)}textarea{width:100%;min-height:85px}button{font:inherit;padding:.7rem 1rem;margin:.5rem .5rem .5rem 0;cursor:pointer}.example,.delivery{background:#f4f8fb;border-left:4px solid #39739d;padding:10px;margin:10px 0}.delivery{border-left-color:#856404;background:#fffaf0}video{display:block;max-width:100%;width:640px;margin:10px 0}.step{border-top:1px solid #e1e5e8;padding-top:12px;margin-top:12px}.muted{color:#5c6872;font-size:.9rem}.error{color:#9b1c1c;font-weight:600}a{color:#075985}</style></head><body><header><h1>Communication Patterns Lab — Practice</h1><p>Local rehearsal for provisional communication-job lessons. <a href="learner-field-guide.md">Read the learner field guide</a> · <a href="communication-job-cards.html">Open lesson cards</a></p></header><main><div class="notice"><b>Boundary:</b> These are practice hypotheses, not proven best practices. This page does not upload responses, require recording or measure effectiveness. Do not imitate a speaker’s identity, accent, personality or mannerism. Use typed, spoken, captioned or asynchronous practice.</div><section class="panel"><label>Choose a communication job <select id="lesson">__OPTIONS__</select></label><p id="status" class="muted"></p><div id="content"></div></section><section class="panel"><h2>Save a local practice record</h2><p class="muted">Use a pseudonymous code. Saving downloads JSON to your device; nothing is sent to this repository.</p><label>Pseudonymous participant code <input id="participant" autocomplete="off" placeholder="e.g. learner-01"></label><label>Accessibility or modality note (optional) <textarea id="accessibility" rows="2"></textarea></label><label><input id="consent" type="checkbox"> I consent to save this local practice record for my own learning log.</label><p id="error" class="error" aria-live="polite"></p><button id="download" type="button">Download local practice JSON</button></section></main><script id="lesson-data" type="application/json">__DATA__</script><script>const lessons=JSON.parse(document.getElementById('lesson-data').textContent),select=document.getElementById('lesson'),content=document.getElementById('content'),status=document.getElementById('status'),error=document.getElementById('error');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const list=v=>Array.isArray(v)?v.map(esc).join('; '):esc(v);let currentResponses={};function renderDelivery(sample){const raw=sample.raw_media_state==='raw_audio_video_present';const media=raw?'<video controls preload="metadata" src="../data/video/'+encodeURIComponent(sample.video_id)+'.mp4"><a href="'+esc(sample.source_url)+'" target="_blank" rel="noopener">Open source context</a></video>':'<p><a href="'+esc(sample.source_url)+'" target="_blank" rel="noopener">Open source context</a> (raw local media unavailable)</p>';return '<div class="delivery"><b>'+esc(sample.sample_id)+'</b> — '+esc(sample.title)+'<p>'+esc(sample.transcript_excerpt)+'</p>'+media+'<p class="muted"><b>Status:</b> '+esc(sample.observation_status)+' · '+esc(sample.measurement_status)+' · matched feature segments: '+esc(sample.matched_feature_segment_count)+'</p><p class="muted"><b>Limits:</b> '+list(sample.measurement_limits)+'</p><p class="muted">Raw media is provided for personal inspection. Internal observations are not independent review, manual vocal listening or evidence of effectiveness.</p></div>'}function render(){const x=lessons[Number(select.value)];currentResponses={};status.textContent=x.status+' · claim level: '+x.claim_level;content.innerHTML='<h2>'+esc(x.canonical_job)+'</h2><p><b>Communication problem:</b> '+esc(x.communication_problem)+'</p><p><b>Why it might help:</b> '+esc(x.mechanism_hypothesis)+'</p><p><b>Repeatable form:</b> '+esc(x.repeatable_form)+'</p><h3>Indexed phrase forms</h3><p class="muted">These are transcript-retrieval families, not scripts or independently validated best practices.</p><p>'+((x.indexed_phrase_forms||[]).map(esc).join(' · ')||'No direct phrase-form family match indexed.')+'</p><h3>Inspect exact examples</h3>'+x.exact_examples.slice(0,3).map(e=>'<div class="example"><a href="'+esc(e.source_url)+'" target="_blank" rel="noopener">Open source context</a><p>'+e.segments.map(s=>'<b>'+esc(s.evidence_id)+'</b> '+esc(s.text)).join(' ')+'</p></div>').join('')+'<h3>Delivery samples (manual/independent review pending)</h3>'+x.delivery_samples.map(renderDelivery).join('')+x.steps.map((step,i)=>'<div class="step"><h3>'+(i+1)+'. '+esc(step.type)+'</h3><p>'+esc(step.prompt)+'</p><textarea data-step="'+esc(step.step_id)+'" aria-label="Response for '+esc(step.step_id)+'" placeholder="Your response (optional unless marked required)"></textarea></div>').join('')+'<p class="muted"><b>Safety:</b> '+esc(x.safety_boundary)+'</p>}function gather(){const r={};document.querySelectorAll('[data-step]').forEach(e=>r[e.dataset.step]=e.value);return r}select.onchange=render;document.getElementById('download').onclick=()=>{error.textContent='';const participant=document.getElementById('participant').value.trim();if(!participant||!document.getElementById('consent').checked){error.textContent='Enter a pseudonymous code and give explicit consent before saving.';return}const x=lessons[Number(select.value)],record={schema_version:'1.0',record_type:'local_communication_practice_record',claim_boundary:'Local practice log only; not learner-validation evidence or effectiveness evidence.',lesson_id:x.lesson_id,pattern_id:x.pattern_id,canonical_job:x.canonical_job,source_evidence_ids:x.exact_examples.flatMap(e=>e.segments.map(s=>s.evidence_id)),delivery_sample_ids:x.delivery_samples.map(s=>s.sample_id),participant_code:participant,consent:true,accessibility_or_modality:document.getElementById('accessibility').value,step_responses:gather(),source_payload:'research/communication-job-mobile-lessons.json',saved_at:new Date().toISOString()};const blob=new Blob([JSON.stringify(record,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='communication-practice-'+x.canonical_job+'.json';a.click();URL.revokeObjectURL(url)};render();</script></body></html>""".replace("__OPTIONS__", options).replace("__DATA__", data)
    # Keep the generated browser script valid after the template is rendered.
    document = document.replace("+'</p>}function gather", "+'</p>'}function gather")
    document = document.replace("+'\n'", "+'\\n'")
    document = document.replace("sample.raw_media_state==='raw_audio_video_present'", "sample.raw_media_state.startsWith('raw_audio_video_present')")
    document = document.replace("let currentResponses={};function renderDelivery", "let currentResponses={};const requireLessonBoundary=x=>{if(x.status!=='provisional_not_validated'||x.claim_level!=='practice_hypothesis'||!String(x.safety_boundary||'').trim())throw new Error('lesson boundary is not eligible for local practice');};function renderDelivery")
    document = document.replace("const x=lessons[Number(select.value)],record={", "const x=lessons[Number(select.value)];requireLessonBoundary(x);const record={")
    capture_html = '<section class="panel" id="rehearsal-capture"><h2>Optional local rehearsal recording</h2><p class="muted">Nothing is uploaded. Recording is optional, requires consent, stays in this browser until you download it, and is not learner-validation evidence.</p><label>Mode <select id="capture-mode"><option value="audio">Audio only</option><option value="audio-video">Audio + video</option></select></label><button id="capture-start" type="button">Start local rehearsal recording</button><button id="capture-stop" type="button" disabled>Stop recording</button><span id="capture-status" class="muted" aria-live="polite"></span><audio id="capture-audio" controls hidden></audio><video id="capture-video" controls hidden></video><p><a id="capture-download" hidden>Download local rehearsal</a></p></section><section class="panel" id="local-history"><h2>Compare local practice versions</h2><p class="muted">Saved versions stay in this browser only. They contain your typed responses and pseudonymous code; recordings remain separate local downloads.</p><button id="save-local" type="button">Save version in this browser</button><label>Import a downloaded practice JSON<input id="import-file" type="file" accept="application/json"></label><button id="import-local" type="button">Import selected version</button><button id="compare-local" type="button">Compare latest two versions</button><button id="clear-local" type="button">Clear local history</button><p id="local-status" class="muted" aria-live="polite"></p><div id="local-list"></div><pre id="local-diff" hidden></pre></section>'
    capture_js = "let captureRecorder=null,captureChunks=[],captureStream=null,captureUrl=null;const captureStart=document.getElementById('capture-start'),captureStop=document.getElementById('capture-stop'),captureMode=document.getElementById('capture-mode'),captureStatus=document.getElementById('capture-status'),captureAudio=document.getElementById('capture-audio'),captureVideo=document.getElementById('capture-video'),captureDownload=document.getElementById('capture-download');captureStart.onclick=async()=>{captureStatus.textContent='';if(!document.getElementById('consent').checked){captureStatus.textContent='Give explicit consent before recording.';return}if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder){captureStatus.textContent='This browser does not provide local recording.';return}try{const video=captureMode.value==='audio-video';captureStream=await navigator.mediaDevices.getUserMedia({audio:true,video:video});captureChunks=[];captureRecorder=new MediaRecorder(captureStream);captureRecorder.ondataavailable=e=>{if(e.data.size)captureChunks.push(e.data)};captureRecorder.onstop=()=>{const blob=new Blob(captureChunks,{type:captureRecorder.mimeType||'video/webm'});if(captureUrl)URL.revokeObjectURL(captureUrl);captureUrl=URL.createObjectURL(blob);const target=video?captureVideo:captureAudio;target.src=captureUrl;target.hidden=false;captureDownload.href=captureUrl;captureDownload.download='local-rehearsal-'+lessons[Number(select.value)].canonical_job+'.webm';captureDownload.hidden=false;captureStatus.textContent='Local recording ready; review it before downloading.'};captureRecorder.start();captureStart.disabled=true;captureStop.disabled=false;captureStatus.textContent='Recording locally; nothing is being uploaded.'}catch(e){captureStatus.textContent='Recording was not started: '+e.message}};captureStop.onclick=()=>{if(captureRecorder&&captureRecorder.state!=='inactive'){captureRecorder.stop();captureStream.getTracks().forEach(t=>t.stop());captureStart.disabled=false;captureStop.disabled=true}};"
    document = document.replace('</section></main><script id="lesson-data"', capture_html+'</main><script id="lesson-data"')
    document = document.replace('<label>Choose a communication job', '<label for="lesson">Choose a communication job')
    document = document.replace('<label>Pseudonymous participant code', '<label for="participant">Pseudonymous participant code')
    document = document.replace('<label>Accessibility or modality note (optional)', '<label for="accessibility">Accessibility or modality note (optional)')
    document = document.replace('<label><input id="consent"', '<label for="consent"><input id="consent"')
    document = document.replace('<label>Mode <select id="capture-mode"', '<label for="capture-mode">Mode <select id="capture-mode"')
    document = document.replace('<label>Import a downloaded practice JSON<input id="import-file"', '<label for="import-file">Import a downloaded practice JSON<input id="import-file"')
    history_js = "const historyKey='communication_patterns_lab_records_v1',localStatus=document.getElementById('local-status'),localList=document.getElementById('local-list'),localDiff=document.getElementById('local-diff');const readLocal=()=>{try{return JSON.parse(localStorage.getItem(historyKey)||'[]')}catch(_){return[]}};const writeLocal=rows=>localStorage.setItem(historyKey,JSON.stringify(rows.slice(-20)));const localRecord=()=>{const participant=document.getElementById('participant').value.trim();if(!participant||!document.getElementById('consent').checked){localStatus.textContent='Enter a pseudonymous code and give explicit consent before saving.';return null}const x=lessons[Number(select.value)];requireLessonBoundary(x);return {schema_version:'1.0',record_type:'local_communication_practice_record',claim_boundary:'Local practice log only; not learner-validation evidence or effectiveness evidence.',lesson_id:x.lesson_id,pattern_id:x.pattern_id,canonical_job:x.canonical_job,source_evidence_ids:x.exact_examples.flatMap(e=>e.segments.map(s=>s.evidence_id)),delivery_sample_ids:x.delivery_samples.map(s=>s.sample_id),participant_code:participant,consent:true,accessibility_or_modality:document.getElementById('accessibility').value,step_responses:gather(),saved_at:new Date().toISOString()}};const renderLocal=()=>{const rows=readLocal();localList.innerHTML=rows.length?rows.map((r,i)=>'<div class=\"muted\">'+(i+1)+'. '+esc(r.canonical_job)+' · '+esc(r.saved_at)+' · '+Object.keys(r.step_responses||{}).length+' responses</div>').join(''):'<p class=\"muted\">No browser-local versions saved.</p>'};document.getElementById('save-local').onclick=()=>{const record=localRecord();if(!record)return;const rows=readLocal();rows.push(record);writeLocal(rows);localStatus.textContent='Saved locally; nothing was uploaded.';renderLocal()};document.getElementById('clear-local').onclick=()=>{if(!readLocal().length){localStatus.textContent='No browser-local versions to clear.';return}if(!window.confirm('Clear all browser-local practice versions? Downloaded files are not deleted.'))return;localStorage.removeItem(historyKey);localDiff.hidden=true;localStatus.textContent='Browser-local practice history cleared.';renderLocal()};document.getElementById('compare-local').onclick=()=>{const rows=readLocal();if(rows.length<2){localStatus.textContent='Save at least two versions before comparing.';return}const a=rows[rows.length-2],b=rows[rows.length-1],keys=[...new Set([...Object.keys(a.step_responses||{}),...Object.keys(b.step_responses||{})])];localDiff.textContent=keys.map(k=>k+'\\n- previous: '+(a.step_responses?.[k]||'')+'\\n+ latest: '+(b.step_responses?.[k]||'')).join('\\n\\n');localDiff.hidden=false;localStatus.textContent='Showing the latest two local versions; this is a reflection aid, not a performance score.'};renderLocal();"
    import_js = "const importFile=document.getElementById('import-file');const importedErrors=record=>{const errors=[];const lesson=lessons.find(x=>x.lesson_id===record.lesson_id);if(!lesson)errors.push('lesson is not in this payload');if(record.record_type!=='local_communication_practice_record'||record.schema_version!=='1.0'||record.consent!==true)errors.push('record type, schema version or consent is invalid');if(typeof record.participant_code!=='string'||!record.participant_code.trim())errors.push('participant code is missing');if(typeof record.accessibility_or_modality!=='string'||typeof record.step_responses!=='object'||record.step_responses===null||Array.isArray(record.step_responses))errors.push('practice response fields are invalid');if(typeof record.claim_boundary!=='string'||!record.claim_boundary.toLowerCase().includes('not')||!record.claim_boundary.toLowerCase().includes('effectiveness'))errors.push('claim boundary is invalid');if(Number.isNaN(Date.parse(record.saved_at)))errors.push('saved timestamp is invalid');if(!Array.isArray(record.source_evidence_ids)||!Array.isArray(record.delivery_sample_ids))errors.push('evidence links are missing');if(lesson){if(lesson.status!=='provisional_not_validated'||lesson.claim_level!=='practice_hypothesis'||!String(lesson.safety_boundary||'').trim())errors.push('lesson boundary is not eligible for local practice');const evidence=new Set(lesson.exact_examples.flatMap(e=>e.segments.map(s=>s.evidence_id))),delivery=new Set(lesson.delivery_samples.map(s=>s.sample_id));if(record.pattern_id!==lesson.pattern_id||record.canonical_job!==lesson.canonical_job)errors.push('lesson and pattern do not agree');if(record.source_evidence_ids.some(id=>!evidence.has(id)))errors.push('transcript evidence link is invalid');if(record.delivery_sample_ids.some(id=>!delivery.has(id)))errors.push('delivery sample link is invalid')}return errors};document.getElementById('import-local').onclick=()=>{const file=importFile.files[0];if(!file){localStatus.textContent='Select a downloaded practice JSON first.';return}const reader=new FileReader();reader.onload=()=>{try{const record=JSON.parse(reader.result),errors=importedErrors(record);if(errors.length){localStatus.textContent='Import rejected: '+errors.join('; ');return}const rows=readLocal();rows.push(record);writeLocal(rows);localStatus.textContent='Imported and saved locally; nothing was uploaded.';renderLocal()}catch(_){localStatus.textContent='Import rejected: invalid JSON.'}};reader.readAsText(file)};"
    document = document.replace('select.onchange=render;', capture_js+history_js+import_js+'select.onchange=render;')
    document = document.replace('.error{color:#9b1c1c;font-weight:600}', '.error{color:#9b1c1c;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%;box-sizing:border-box}')
    document = document.replace('<title>Communication Patterns Lab — Practice</title>', '<title>Communication Patterns Lab — Practice</title><link rel="manifest" href="communication-patterns-lab.webmanifest">')
    document = document.replace('</body></html>', '<script>if("serviceWorker" in navigator && location.protocol !== "file:"){navigator.serviceWorker.register("communication-patterns-lab-sw.js").catch(()=>{});}</script></body></html>')
    OUT.write_text(document)
    print(f"wrote {OUT.relative_to(ROOT)} ({len(lessons)} lessons)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
